var d = System.AppDomain.CurrentDomain;
string log = "";
try { if (PauseController.pauseStatus != PauseStatus.UnPaused) { PauseController.SetPause(PauseStatus.UnPaused); log += "unpaused "; } } catch (System.Exception ex) { log += "unpause failed: " + ex.Message + " "; }
if (UnityEngine.Time.timeScale != 1f) { UnityEngine.Time.timeScale = 1f; log += "speed1 "; }
try { if (d.GetData("uimtest.joined") != null && HeroController.IsPlaying(1)) { HeroController.Dropout(1, false); log += "dropped1 "; } } catch (System.Exception ex) { log += "dropout failed: " + ex.Message + " "; }
d.SetData("uimtest.joined", null);
var hc = d.GetData("uimtest.ironbro") as string;
d.SetData("uimtest.ironbro", null);
try {
  var save = GameState.Instance.currentWorldmapSave;
  if (hc != null && save != null) {
    var parts = hc.Split(':');
    save.worldMapIsHardcoreCampaign = parts[0] == "1";
    save.hardcoreLives = int.Parse(parts[1]);
    save.hardcoreModeAvailableBros.Clear();
    foreach (var n in parts[2].Split(',')) if (n.Length > 0) save.hardcoreModeAvailableBros.Add((HeroType)System.Enum.Parse(typeof(HeroType), n));
    log += "ironbro-restored ";
  }
} catch (System.Exception ex) { log += "ironbro restore failed: " + ex.Message + " "; }
var lk = d.GetData("uimtest.lock") as string;
d.SetData("uimtest.lock", null);
try {
  if (lk != null) {
    var fl = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static;
    var t = System.Type.GetType("BroMakerLib.Unlocks.BroUnlockManager, BroMakerLib");
    var pd = t.GetField("progressData", fl).GetValue(null);
    var states = pd.GetType().GetProperty("BroStates").GetValue(pd, null) as System.Collections.IDictionary;
    var st = states[lk];
    st.GetType().GetProperty("IsUnlocked").SetValue(st, true, null);
    st.GetType().GetProperty("UnlockedDate").SetValue(st, d.GetData("uimtest.lock.date"), null);
    var names = t.GetProperty("UnlockedBroNames", fl).GetValue(null, null) as System.Collections.Generic.List<string>;
    var bros = t.GetProperty("UnlockedBros", fl).GetValue(null, null) as System.Collections.IList;
    int ni = (int)d.GetData("uimtest.lock.ni"); if (ni < 0 || ni > names.Count) ni = names.Count;
    if (!names.Contains(lk)) names.Insert(ni, lk);
    var hero = d.GetData("uimtest.lock.hero");
    int hi = (int)d.GetData("uimtest.lock.hi"); if (hi < 0 || hi > bros.Count) hi = bros.Count;
    if (hero != null && !bros.Contains(hero)) bros.Insert(hi, hero);
    typeof(BroMakerLib.Storages.BroSpawnManager).GetMethod("BroStatusChanged", fl).Invoke(null, null);
    log += "unlocked " + lk + " ";
  }
} catch (System.Exception ex) { log += "unlock failed: " + ex.Message + " "; }
var sw = d.GetData("uimtest.swap") as string;
d.SetData("uimtest.swap", null);
try {
  if (sw != null) {
    var p = sw.Split('|');
    var set = Swap_Bros_Mod.Main.settings;
    set.alwaysChosen = p[0] == "True";
    set.ignoreCurrentUnlocked = p[1] == "True";
    Swap_Bros_Mod.Main.LoadCustomBros();
    Swap_Bros_Mod.Main.CreateBroList();
    var l = Swap_Bros_Mod.Main.currentBroList;
    for (int i = 0; i < 4; i++) { int ix = l.IndexOf(p[2 + i]); set.selGridInt[i] = ix < 0 ? 0 : ix; }
    log += "swap-settings-restored ";
  }
} catch (System.Exception ex) { log += "swap settings restore failed: " + ex.Message + " "; }
return log.Length == 0 ? "nothing to restore" : log;

var d = System.AppDomain.CurrentDomain;
var sc = UnityEngine.SceneManagement.SceneManager.GetActiveScene().name;
